edits.new_string:
local motors={}
local trails={}
for _,v in model:GetDescendants() do
 if v:IsA("Motor6D") and string.find(v.Name,"WingMotor_",1,true) then
  table.insert(motors,{motor=v,side=v:GetAttribute("GBloxWingSide")=="L" and -1 or 1})
 elseif v:IsA("Trail") and v.Name=="GBloxVelocityTrail" then
  table.insert(trails,v)
 end
end
states[player][slot]={slot=slot,model=model,root=root,motors=motors,trails=trails,rotationOffset=rotationOffset,cf=nil,last=nil,phase=math.random()*math.pi*2}
